    const MIN_SIZE: usize = {
        let sizes = [
            <Device as Table>::MIN_SIZE,
            <VariationIndex as Table>::MIN_SIZE,
        ];
        let mut min = usize::MAX;
        let mut i = 0;
        while i < sizes.len() {
            if sizes[i] < min {
                min = sizes[i];
            }
            i += 1;
        }
        min
    };

