impl<'a> Table<'a> for Condition<'a> {
    type Args = ();

    /// The smallest of the variants: which one is present is not known
    /// until the format word is read.
    const MIN_SIZE: usize = {
        let sizes = [
            <ConditionFormat1 as Table>::MIN_SIZE,
            <ConditionFormat2 as Table>::MIN_SIZE,
            <ConditionFormat3 as Table>::MIN_SIZE,
            <ConditionFormat4 as Table>::MIN_SIZE,
            <ConditionFormat5 as Table>::MIN_SIZE,
        ];
        let mut min = usize::MAX;
        let mut i = 0;
        while i < sizes.len() {
            if sizes[i] < min {
                min = sizes[i];
            }
            i += 1;
        }
        min
    };
    fn read_with_args(data: Bytes<'a>, _: ()) -> Option<Self> {
        let format: u16 = data.read_at(0usize)?;
        match format {
            ConditionFormat1::FORMAT => Some(Self::Format1AxisRange(
                <ConditionFormat1 as Table<'a>>::read(data)?,
            )),
            ConditionFormat2::FORMAT => {
                Some(Self::Format2VariableValue(<ConditionFormat2 as Table<
                    'a,
                >>::read(data)?))
            }
            ConditionFormat3::FORMAT => Some(Self::Format3And(
                <ConditionFormat3 as Table<'a>>::read(data)?,
            )),
            ConditionFormat4::FORMAT => Some(Self::Format4Or(
                <ConditionFormat4 as Table<'a>>::read(data)?,
            )),
            ConditionFormat5::FORMAT => Some(Self::Format5Negate(<ConditionFormat5 as Table<
                'a,
            >>::read(data)?)),
            _ => None,
        }
    }
}

